Ví dụ 3.4 Ví dụ sau minh họa việc sử dụng hàm inline trong lớp:
#include <iostream>
#include <string.h>
#include <conio.h>
using namespace std;
class phrase
{
private:
   char dongtu[10];
   char danhtu[10];
   char cumtu[25];
public:
   phrase();
   inline void set_danhtu(char* in_danhtu);
   inline void set_dongtu(char* in_dongtu);

    inline char* get_phrase(void);
};
void phrase::phrase()
{
    strcpy(danhtu,"");
    strcpy(dongtu,"");
    strcpy(cumtu,"");
}
inline void phrase::set_danhtu(char* in_danhtu)
{
    strcpy(danhtu, in_danhtu);
}
inline void phrase::set_dongtu(char* in_dongtu)
{
    strcpy(dongtu, in_dongtu);
}
inline char* phrase::get_phrase(void)
{
    strcpy(cumtu,dongtu);
    strcat(cumtu," the ");
    strcat(cumtu,danhtu);
    return cumtu;
}
main()
{
   phrase text;
   cout <<"Cum tu la : -> "<<text.get_phrase()<<
"\n";
   text.set_danhtu("file");
   cout<<"Cum tu la:->"<< text.get_phrase()<< " \ n
";
   text.set_dongtu("Save");
   cout << "Cum tu la : ->"
<<text.get_phrase()<<"\n";
   text.set_danhtu("program");
   cout <<"Cum tu la : ->"<<text.get_phrase()<<"\n";
}
Kết quả chương trình như sau:

Cum tu la : -> the

Cum tu la : -> the file

       Cum tu la : -> Save the file

       Cum tu la : -> Save the program

    3.4. Con trỏ đối tượng

       Con trỏ đối tượng dùng để chứa địa chỉ của biến, mảng đối tượng. Nó được
khai báo như sau:

       Tên_lớp *con trỏ ;

  Ví dụ dùng lớp DIEM có thể khai báo:

     DIEM *p1 , *p2, *p3 ; // khai báo 3 con trỏ p1, p2, p3

     DIEM d1, d2 ; // Khai báo 2 đối tượng d1, d2

     DIEM d[20] ; // Khai báo mảng đối tượng

Ta có thể thực hiện các câu lệnh:

     p1 = &d2 ; // p1 chứa địa chỉ của d2 , hay p1 trỏ tới d2

     p2 = d ;    // p2 trỏ tới đầu mảng d

     p3 = new DIEM // Tạo một đối tượng và chứa địa chỉ của nó vào p3

       Để sử dụng thuộc tính của đối tượng thông qua con trỏ, ta viết như sau:

     Tên_con_trỏ->Tên_thuộc_tính

Chú ý: Nếu con trỏ chứa địa chỉ đầu của mảng, có thể dùng con trỏ như tên mảng.

Như vậy sau khi thực hiện các câu lệnh trên thì:

     p1->x và d2.x là như nhau

       p2[i].y và d[i].y là như nhau

Tóm lại ta có quy tắc sau

       Quy tắc sử dụng thuộc tính: Để sử dụng một thuộc tính của đối tượng ta phải
dùng phép . hoặc phép -> . Trong chương trình, không cho phép viết tên thuộc tính một
cách đơn độc mà phải đi kèm tên đối tượng hoặc tên con trỏ theo các mẫu sau:

Tên_đối_tượng.Tên_thuộc_tính

Tên_con_trỏ->Tên_thuộc_tính

Tên_mảng_đối_tượng[chỉ_số].Tên_thuộc_tính

Tên_con_trỏ[chỉ_số].Tên_thuộc_tính

