    3.5. Con trỏ this

       3.5.1. Con trỏ this là đối thứ nhất của phương thức

       C++ sử dụng con trỏ đặc biệt this trong các phương thức. Các thuộc tính viết
trong phương thức được hiểu là thuộc một đối tượng do con trỏ this trỏ tới. Như vậy
phương thức nhapsl() có thể viết một cách tường minh như sau:

  void DIEM::nhapsl()
   {
      cout << "\n Nhap hoanh do va tung do cua diem:";
      cin >>this->x>>this->y ;
   }
     Từ góc độ hàm số có thể kết luận rằng: Phương thức bao giờ cũng có ít nhất
một đối là con trỏ this và nó luôn luôn là đối đầu tiên của phương thức.

      3.5.2. Tham số ứng với đối con trỏ this

                DIEM d1;

                d1.nhapsl() ;

        Trong trường hợp này tham số truyền cho con trỏ this chính là địa chỉ của d1:

     this = &d1

       Do đó:

                this->x chính là d1.x

                this->y chính là d1.y

       Như vậy câu lệnh d1.nhapsl() ; sẽ nhập dữ liệu cho các thuộc tính của đối tượng
d1. Từ đó có thể rút ra kết luận sau:

       Tham số truyền cho đối con trỏ this chính là địa chỉ của đối tượng đi kèm với
phương thức trong lời gọi phương thức.

  Ví dụ 3.6:
  #include <conio.h>
  #include <iostream>

  #include<math.h>
  using namespace std;
  class DIEM
  {
       private :
             int x,y ;
       public :
        void nhapsl( )
        {
          cout << "\n Nhap hoanh do va tung do cua diem:";
          cin >>x>>y ;
        }
          void hienthi( )
          { cout<<"\n x = " <<x<<" y = "<<y<<endl;}
          double do_dai(DIEM d2)
          {
             return sqrt( pow(this->x - d2.x,2) +pow(this->y -
             d2.y,2) ) ;
          }
  } ;
  main()
  {
         DIEM d1,d2;
         double kc;
         d1.nhapsl();
         d2.nhapsl();
         kc =d1. do_dai(d2);
         cout<<"Khoang cach 2 diem vua nhap la: "<<kc;
   }
    3.6. Hàm bạn

       Trong thực tế thường xãy ra trường hợp có một số lớp cần sử dụng chung một
hàm. C++ giải quyết vấn đề này bằng cách dùng hàm bạn. Để một hàm trở thành bạn
của một lớp, có 2 cách viết:

       Cách 1: Dùng từ khoá friend để khai báo hàm trong lớp và xây dựng hàm bên
ngoài như các hàm thông thường (không dùng từ khoá friend). Mẫu viết như sau:

class A

     {

         private:

           // Khai báo các thuộc tính

         public:

           ...

           // Khai báo các hàm bạn của lớp A

           friend void f1(...);

           friend double f2(...);

           friend A f3(...) ;

                 ...

     };

// Xây dựng các hàm f1, f2, f3

void f1(...)

 {

     ...

 }

double f2(...)

 {

     ...

 }

A f3(...)

 {

     ...

   }

           Cách 2: Dùng từ khoá friend để xây dựng hàm trong định nghĩa lớp. Mẫu viết
như sau:

  class A

       {

           private:

             // Khai báo các thuộc tính

           public:

             ...

             // Xây dựng các hàm bạn của lớp A

             void f1(...)

               {

                   ...

               }

             double f2(...)

               {

                   ...

               }

             A f3(...)

               {

                   ...

               }

             ...

       };

         Hàm bạn có những tính chất sau:

         + Trong thân hàm bạn của một lớp có thể truy nhập tới các thuộc tính của các
đối tượng thuộc lớp này. Đây là sự khác nhau duy nhất giữa hàm bạn và hàm thông
thường.

         + Hàm bạn không phải là phương thức của lớp

         + Việc truy nhập tới hàm bạn được thực hiện như hàm thông thường.

         Ví dụ sau sẽ so sánh phương thức, hàm bạn và hàm tự do (hàm thông thường).
Xét lớp SP (số phức). Hãy so sánh 3 phương án để thực hiện việc cộng 2 số phức:

  Phương án 1: Dùng phương thức

  class SP

     {

         private:

           double a; // Phần thực

           double b; // Phần ảo

         public:

           SP cong(SP u2)

             {

                 SP u:

                 u.a = this->a + u2.a ;

                 u.b = this->b + u2.b ;

                 return u;

             }

     };

  Cách dùng

  SP u, u1, u2;

  u = u1.cong(u2);

Phương án 2: Dùng hàm bạn

class SP

  {

      private:

        double a; // Phần thực

        double b; // Phần ảo

      public:

        friend SP cong(SP u1, SP u2)

           {

               SP u:

               u.a = u1.a + u2.a ;

               u.b = u1.b + u2.b ;

               return u;

           }

  };

Cách dùng

  SP u, u1, u2;

  u = cong(u1, u2);

Phương án 3: Dùng hàm tự do

class SP

  {

      private:

             double a; // Phần thực

             double b; // Phần ảo

         public:

             ...

        };

  SP cong(SP u1, SP u2)

    {

        SP u:

        u.a = u1.a + u2.a ;

        u.b = u1.b + u2.b ;

        return u;

    }

          Phương án này không được chấp nhận, Trình biên dịch sẽ báo lỗi vì trong thân
hàm không được quyền truy xuất đến các thuộc tính riêng (private) a, b của các đối
tượng u, u1 và u2 thuộc lớp SP.

          Một hàm có thể là bạn của nhiều lớp. Lúc đó nó có quyền truy nhập tới tất cả
các thuộc tính của các đối tượng trong các lớp này. Để làm cho hàm f trở thành bạn của
các lớp A, B và C ta sử dụng mẩu viết sau :

                        class B ; //Khai báo trước lớp A

                        class B ; // Khai báo trước lớp B

                        class C ; // Khai báo trước lớp C

                        // Định nghĩa lớp A

          Chương trình sau đây minh hoạ cách dùng hàm bạn (bạn của một lớp và bạn
của nhiều lớp). Chương trình đưa vào 2 lớp VT (véc tơ), MT (ma trận) và 3 hàm bạn để
thực hiện các thao tác trên 2 lớp này:

       // Hàm bạn với lớp VT dùng để in một véc tơ

       friend void in(const VT &x);

       // Hàm bạn với lớp MT dùng để in một ma trận

       friend void in(const MT &a);

       // Hàm bạn với cả 2 lớp MT và VT dùng để nhân ma trận với véc tơ

       friend VT tich(const MT &a,const VT &x);

       Nội dung chương trình là nhập một ma trận vuông cấp n và một véc tơ cấp n,
sau đó thực hiện phép nhân ma trận với véc tơ vừa nhập.

  Ví dụ 3.7:
  #include <conio.h>
  #include <iostream>
  #include <math.h>
  using namespace std;
  class VT;
  class MT ;
  class VT
  {
     private:
          int n;
          double x[20]; // Toa do cua diem
          public:
          void nhapsl();
          friend void in(const VT &x);
          friend VT tich(const MT &a,const VT &x) ;
     } ;
     class MT
     {
          private:
               int n;
               double a[20][20];
               public:
               friend VT tich(const MT &a,const VT &x);
               friend void in(const MT &a);

        void nhapsl();
} ;
void VT::nhapsl()
{
    cout << "\n Cap vec to = ";
    cin >> n ;
    for (int i=1; i<=n ; ++i)
    {
          cout << "\nPhan tu thu " << i << " = " ;
          cin >> x[i];
    }
}
void MT::nhapsl()
{
    cout << "\n Cap ma tran = ";
    cin >> n ;
    for (int i=1; i<=n ; ++i)
       for (int j=1; j<=n; ++j)
       {
          cout << "\nPhan tu thu hang "<< i << " cot "
          << j << "=" ;
          cin >> a[i][j];
       }
}
VT tich(const MT &a,const VT &x)
{
    VT y;
    int n=a.n;
    if (n!=x.n)
    return x;
    y.n = n;
    for (int i=1; i<=n; ++i)
    {
          y.x[i]=0;
          for (int j=1; j<=n; ++j)
          y.x[i] += a.a[i][j]*x.x[j];
    }
     return y;

      }
      void in(const VT &x)
      {
          cout << "\n";
          for (int i=1; i<=x.n; ++i)
          cout << x.x[i] << " ";
      }
      void in(const MT &a)
      {
          for (int i=1; i<=a.n; ++i)
          {
               cout << "\n" ;
               for (int j=1; j<=a.n; ++j)
               cout << a.a[i][j] << " ";
          }
      }
      main()
      {
          MT a; VT x,y;
          a.nhapsl();
          x.nhapsl();
          y=tich(a,x);
          cout << "\nMa tran A:";
          in(a);
          cout << "\n\nVec to x: " ;
          in(x);
          cout << "\n\nVec y = Ax: " ;
          in(y);
      }
 3.7. Dữ liệu thành phần tĩnh và hàm thành phần tĩnh

   3.7.1. Dữ liệu thành phần tĩnh

      + Thành phần dữ liệu được khai báo bằng từ khoá static gọi là tĩnh, ví dụ:

class A

  {

      private:

            static int ts ; // Thành phần tĩnh

            int    x;

            ....

       };

         + Thành phần tĩnh được cấp phát một vùng nhớ cố định. Nó tồn tại ngay cả khi
lớp chưa có một đối tượng nào cả.

         + Thành phần tĩnh là chung cho cả lớp, nó không phải là riêng của mỗi đối
tượng. Ví dụ xét 2 đối tượng:

       A u,v ; // Khai báo 2 đối tượng

         thì giữa các thành phần x và ts có sự khác nhau như sau:

       u.x và v.x có 2 vùng nhớ khác nhau

       u.ts và v.ts chỉ là một, chúng cùng biểu thị một vùng nhớ

         thành phần ts tồn tại ngay khi u và v chưa khai báo

         + Để biểu thị thành phần tĩnh, ta có thể dùng tên lớp, ví du: Đối với ts thì 3
cách viết sau là tương đương: A::ts              u.ts          v.ts

         + Khai báo và khởi gán giá trị cho thành phần tĩnh

  Thành phần tĩnh sẽ được cấp phát bộ nhớ và khởi gán giá trị ban đầu bằng một câu
lệnh khai báo đặt sau định nghĩa lớp (bên ngoài các hàm, kể cả hàm main), theo các
mẫu:

       int A::ts ;        // Khởi gán cho ts giá trị 0

       int A::ts = 1234; // Khởi gán cho ts giá trị 1234

  Chú ý: Khi chưa khai báo thì thành phần tĩnh chưa tồn tại. Ví dụ xét chương trình
sau:

         Ví dụ 3.8

       #include <conio.h>

     #include <iostream>
     using namespace std;
     class HDBH
     {
       private:
             char *tenhang;
             double tienban;
             static int tshd;
             static double tstienban;
             public:
             static void in()
             {
                    cout <<"\n" << tshd;
                    cout <<"\n" << tstienban;
             }
     };
       main ()
     {
       HDBH::in();
     }
       Các thành phần tĩnh tshd và tstienban chưa khai báo, nên chưa tồn tại. Vì vậy
các câu lệnh in giá trị các thành phần này trong hàm in() là không thể được. Khi dịch
chương trình, sẽ nhận được các thông báo lỗi. Có thể sửa chương trình trên bằng cách
đưa vào các lệnh khai báo các thành phần tĩnh tshd và tstienban như sau:

       Ví dụ 3.9
       #include <conio.h>
       #include <iostream>
       using namespace std;
       class HDBH
       {
           private:
                int shd;
                char *tenhang;
                double tienban;
                static int tshd;
                static double tstienban;
                public:

                    static void in()
                    {
                         cout <<"\n" << tshd;
                         cout <<"\n" << tstienban;
                    }
       };
       int HDBH::tshd=5;
       double HDBH::tstienban=20000.0;
       main ()
       {
           HDBH::in();
       }
      3.7.2. Hàm thành phần tĩnh

       Hàm thành phần tĩnh được viết theo một trong hai cách:

     - Dùng từ khoá static đặt trước định nghĩa hàm thành phần viết bên trong định
nghĩa lớp.

     - Nếu hàm thành phần xây dựng bên ngoài định nghĩa lớp, thì dùng từ khoá static
đặt trước khai báo hàm thành phần bên trong định nghĩa lớp. Không cho phép dùng từ
khoá static đặt trước định nghĩa hàm thành phần viết bên ngoài định nghĩa lớp.

     Các đặc tính của hàm thành phần tĩnh:

     - Hàm thành phần tĩnh là chung cho toàn bộ lớp và không lệ thuộc vào một đối
tượng cụ thể, nó tồn tại ngay khi lớp chưa có đối tượng nào.

     - Lời gọi hàm thành phần tĩnh như sau:

                Tên lớp :: Tên hàm thành phần tĩnh(các tham số thực sự)

     - Vì hàm thành phần tĩnh là độc lập với các đối tượng, nên không thể dùng hàm
thành phần tĩnh để xử lý dữ liệu của các đối tượng trong lời gọi phương thức tĩnh. Nói
cách khác không cho phép truy nhập các thuộc tính (trừ thuộc tính tĩnh) trong thân hàm
thành phần tĩnh. Đoạn chương trình sau minh họa điều này:
       class HDBH
       {
        private:
           int shd;

     char *tenhang;
     double tienban;
     static int tshd;
     static double tstienban;
 public:
   static void in()
   {
     cout <<”\n” << tshd;
     cout << ”\n” << tstienban;
     cout <<”\n”<< tenhang        //loi
     cout <<”\n” << tienban; //loi
   }
};
Ví dụ 3.10
#include <iostream>
