    T1.PrintStandard();
   cout << endl << " Tham so cho gio. Phut va giay
   mac dinh:" << endl << " ";
    T2.PrintMilitary(); cout << endl << " ";
    T2.PrintStandard();
   cout << endl << "Tham so cho gio, phut. Giay mac
   dinh:" << endl << " ";
    T3.PrintMilitary(); cout << endl << " ";
   T3.PrintStandard(); cout << endl << "Tham so cho
   gio , phut va giay:"<<endl<<" ";
    T4.PrintMilitary(); cout << endl << " ";
    T4.PrintStandard();
    return 0;
}
