#include <iostream>
#include <string.h>
#include <conio.h>
using namespace std;
class String
{ char s[80];
   public:
     String() { *s='\0'; }
     String(char *p) { strcpy(s,p); }
     char *get() { return s;}
     String operator + (String s2);
     String operator = (String s2);
     int operator < (String s2);
     int operator > (String s2);
     int operator == (String s2);
};
String String::operator +(String s2)
{
 strcat(s,s2.s);
 return *this ;
}

String String::operator =(String s2)
{
 strcpy(s,s2.s) ;

     return *this;
   }
   int String::operator <(String s2)
   {
      return strcmp(s,s2.s)<0 ;
   }
   int String::operator >(String s2)
   {
      return strcmp(s,s2.s)>0 ;
   }
   int String::operator ==(String s2)
   {
      return strcmp(s,s2.s)==0 ;
   }
   main()
   {
      String s1 ("Trung Tam "), s2 (" Tin hoc"), s3;
      cout<<"s1 = "<<s1.get()<<'\n';
      cout<<"s2 = "<<s2.get()<<'\n';
      if (s1 > s2)
         cout << "s1 > s2 \n";
      if (s1 < s2)
         cout << "s1 < s2 \n";
      if (s1 == s2)
         cout << "s1 bang s3 \n";
      s3=s1+s2;
      cout<<"s3 ="<<s3.get()<<'\n'; //Trung tam tin hoc
      s3=s2;
      cout<<"s2 = "<<s2.get()<<'\n'; //Tin hoc
      cout<<"s3 = "<<s3.get()<<'\n'; //Tin hoc
      if (s2 == s3)
         cout << "s2 bang s3 \n";
   }
4.4. Định nghĩa chồng các toán tử ++ , --

  Ta có thể định nghĩa chồng cho các toán tử ++/-- theo quy định sau:

  - Toán tử ++/-- dạng tiền tố trả về một tham chiếu đến đối tượng thuộc lớp.

  - Toán tử ++/-- dạng hậu tố trả về một đối tượng thuộc lớp

  Ví dụ 4.10

#include <iostream>
#include <conio.h>
using namespace std;
class Diem
{
    private:
      int x,y;
    public:
      Diem() {x = y = 0;}
      Diem(int x1, int y1)
      {x = x1;
       y = y1;}
     Diem & operator ++(); //toan tu ++ tien to
     Diem operator ++(int); //toan tu ++ hau to
     Diem & operator --(); //toan tu -- tien to
     Diem operator --(int); //toan tu -- hau to
     void hienthi()
     {
         cout<<" x = "<<x<<" y = "<<y;
     }
    };
Diem & Diem::operator ++()
 {
    x++;
    y++;
    return (*this);
   }
Diem Diem::operator ++(int)
 {
    Diem temp = *this;
    ++*this;
    return temp;
   }
Diem & Diem::operator --()
 {
    x--;
    y--;
    return (*this);
   }
Diem Diem::operator --(int)
 {
    Diem temp = *this;
    --*this;

   return temp;
   }
main()
   {
      Diem d1(5,10),d2(20,25),d3(30,40),d4(50,60);
      cout<<"\nd1 : ";d1.hienthi();
      ++d1;
     cout<<"\n Sau khi tac dong cac toan tu tang truoc
     :";
      cout<<"\nd1 : ";d1.hienthi();
      cout<<"\nd2 : ";d2.hienthi();
      d2++;
      cout<<" \n cac toan tu tang sau";
      cout<<"\nd2 : ";d2.hienthi();
      cout<<"\nd3 : ";d3.hienthi();
      --d3;
     cout<<"\n cac toan tu giam truoc :";
      cout<<"\nd3 : ";d3.hienthi();
      cout<<"\nd4 : ";d4.hienthi();
      d4--;
     cout<<"\n cac toan tu giam sau : ";
      cout<<"\nd4 : ";d4.hienthi();
   }
Chương trình cho kết quả như sau:

d1 : x = 5 y = 10

Cac toan tu tang truoc :

d1 : x = 6 y = 11

d2 : x = 20 y = 25

Cac toan tu tang sau

d2 : x = 21 y = 26

d3 : x = 30 y = 40

Cac toan tu giam truoc :

d3 : x = 29 y = 39

d4 : x = 50 y = 60

       Cac toan tu giam sau :

       d4 : x = 49 y = 59

       Chú ý: Đối số int trong dạng hậu tố là bắt buộc, dùng để phân biệt với dạng
tiền tố, thường nó mang trị mặc định là 0.

    4.5. Định nghĩa chồng toán tử << và >>

       Ta có thể định nghĩa chồng cho hai toán tử vào/ra << và >> kết hợp với cout và
cin (cout<< và cin>>), cho phép các đối tượng đứng bên phải chúng. Lúc đó ta có thể
thực hiện các thao tác vào ra như nhập dữ liệu từ bàn phím cho các đối tượng, hiển thị
giá trị thành phần dữ liệu của các đối tượng ra màn hình. Hai hàm toán tử << và >>
phải là hàm tự do và khai báo là hàm bạn của lớp.

       Ví dụ 4.11
       #include <iostream>
